const SUPA = 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1';
const hdr = { apikey: $credentials.supabaseApi.apiKey, Authorization: `Bearer ${$credentials.supabaseApi.apiKey}` };
const weekAgo = new Date(Date.now() - 7*86400000).toISOString();
const [decidedBets, customers, completed, contacts] = await Promise.all([
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/bets?status=in.(won,lost)&decided_at=gte.${weekAgo}&select=hypothesis,kind,status,learning,actual_mrr_impact_usd`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customers?select=kind,mrr_usd,became_paid_at,churned_at,product`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/tasks?status=eq.done&completed_at=gte.${weekAgo}&select=title,agent,workstream`, headers: hdr, json: true }),
  this.helpers.httpRequest({ method: 'GET', url: `${SUPA}/customer_contacts?contacted_at=gte.${weekAgo}&select=summary,reason`, headers: hdr, json: true }),
]);
const paidAdded = customers.filter(c => c.kind === 'paid' && c.became_paid_at >= weekAgo);
const churned   = customers.filter(c => c.kind === 'churned' && c.churned_at >= weekAgo);
const mrrDelta  = paidAdded.reduce((s,c)=>s+(Number(c.mrr_usd)||0),0) - churned.reduce((s,c)=>s+(Number(c.mrr_usd)||0),0);
return [{ json: { decidedBets, weekTasksDone: completed.length, contactCount: contacts.length, paidAdded: paidAdded.length, churned: churned.length, mrrDelta, sampleTasks: completed.slice(0,8), sampleContacts: contacts.slice(0,6) } }];

const blocks = $input.first().json.content || [];
const text = blocks.map(b=>b.text||'').join('').trim();
let retro = null;
try { const a=text.indexOf('{'); const b=text.lastIndexOf('}'); if (a>=0 && b>a) retro = JSON.parse(text.slice(a,b+1)); } catch {}
return [{ json: { retro: retro || { what_worked: [], what_flopped: [], next_focus: text } } }];
